        // Verify storage slot 0 ownership change
        ownerSlot = vm.load(address(proxy), bytes32(0));
        address newOwner = address(uint160(uint256(ownerSlot)));
        assertEq(newOwner, attacker, "Delegatecall attack failed");

        // Verify transaction counters were updated
        assertEq(proxy.totalTransactions(), 1, "Total transactions not updated");
